import React from 'react';
import { motion } from 'framer-motion';
import { X, Sparkles } from 'lucide-react';
import '../styles/AiAnalysisSidebar.css'; // Will create this CSS file too

const AiAnalysisSidebar = ({ isOpen, onClose, data, loading }) => {
  if (!isOpen) return null;

  return (
    <motion.div
      className="ai-analysis-sidebar-overlay"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      onClick={onClose}
    >
      <motion.div
        className="ai-analysis-sidebar"
        initial={{ x: '100%' }}
        animate={{ x: 0 }}
        exit={{ x: '100%' }}
        transition={{ type: 'spring', stiffness: 300, damping: 30 }}
        onClick={(e) => e.stopPropagation()} // Prevent closing when clicking inside
      >
        <div className="sidebar-header">
          <h2><Sparkles size={24} /> Hire Logic AI Analysis</h2>
          <button onClick={onClose} className="btn-close-sidebar" type="button">
            <X size={24} />
          </button>
        </div>

        <div className="sidebar-content">
          {loading ? (
            <div className="ai-loading-state">
              <Sparkles size={48} className="spinning" />
              <p>Analyzing candidate fit with Hire Logic AI...</p>
            </div>
          ) : data ? (
            <>
              <div className="ai-grade-section">
                <h3>Fit Grade: <span className={`ai-grade grade-${data.grade?.toLowerCase()}`}>{data.grade}</span></h3>
              </div>
              <div className="ai-summary-section">
                <h3>Summary</h3>
                <p>{data.summary}</p>
              </div>
            </>
          ) : ( 
            <div className="ai-error-state">
              <p>No analysis data available or an error occurred.</p>
            </div>
          )}
        </div>
      </motion.div>
    </motion.div>
  );
};

export default AiAnalysisSidebar;
